// Commit-window hook + barrier around env.DB.batch (identical technique to the ROUND30 suites).
const realBatch=env.DB.batch.bind(env.DB);let beforeCommit=null,afterCommit=null,barrier=null;
env.DB.batch=async list=>{if(barrier){barrier.arrived++;if(barrier.arrived===barrier.n)barrier.open();await barrier.gate;}const f=beforeCommit;beforeCommit=null;if(f)f();const out=await realBatch(list);const g=afterCommit;afterCommit=null;if(g)g();return out;};
const withBarrier=async(n,fn)=>{let open;barrier={n,arrived:0,gate:new Promise(r=>open=r)};barrier.open=open;try{return await fn()}finally{barrier=null}};
