  for(const k of SIGNOFF_DOMAINS){const x=await req(`/api/styles/${id}/releases/${r.data.releaseNo}/signoffs`,{body:{roleKey:k,decision:'APPROVED'},cookie:cookieOf[signers[k]]});if(x.r.status!==200)throw new Error('fixture signoff '+k+' '+JSON.stringify(x.data));}
