 row(T,'P1A-01','QC signer active but role QC_MANAGER→OPERATOR between pre-checks and PREPARE batch','409 SIGNOFF_SIGNER_INVALID; zero package/event/receipt/audit; nothing to dispatch/ack/open',`${p.r.status} ${p.data.code} active=${active} rowsUnchanged=${same(before,after)} dispatch=${d?.r.status??'n/a'}`,p.r.status===409&&p.data.code==='SIGNOFF_SIGNER_INVALID'&&p.data.roleKey==='QC'&&active===1&&same(before,after)&&!d);
